export class CreateMeasurementConfigurationResponse extends BasicResponseDTO {
    /**
     * Unique identifier assigned by Paigo
     */
    public measurementId: MeasurementConfigEntity['measurementId'];

    /**
     * The configuration of the measurement, including any access information generated by Paigo.
     * Only returned for measurement modes where Paigo provisions access, like `datastoreBased`.
     */
    @ApiProperty({
        required: false,
        type: 'object',
