import { Tag } from '@aws-sdk/client-ec2';
import { S3 } from '@aws-sdk/client-s3';
import { randomUUID } from 'crypto';
import EventEmitter from 'events';
import { AuditService } from '../../audit/audit.service';
import { AuditScope } from '../../audit/entities/audit.interface';
import { InfluxService } from '../../influx/influx.service';
import { MeasurementFormat } from './measurement.interface';

const eventEmitter = new EventEmitter();

/**
 * The suffix given to every failed record stored in the Dead Letter Queue
 */
export const DLQ_MESSAGE_SUFFIX = '.message.text';

/**
 * A failure which occurred while processing a usage record delivered through a datastore
 */
export interface MeasurementFailure {
    /**
     * The key of the object the failed record was delivered in.
     * Can either be relative to the ingestion bucket, or an absolute location like `s3://bucket/key`
     */
    s3Key?: string;
    sourceKey?: string;
    key?: string;
    /**
     * The input which failed processing
     */
    message?: any;
    input?: any;
    /**
     * The error which caused the failure
     */
    error?: any;
    businessID?: string;
    /**
     * Overrides the bucket the failure is delivered to, defaults to `DB_MEASUREMENT_DLQ_BUCKET_NAME`
     */
    bucket?: string;
}

    static awsTagKeyReducer(Tags: Tag[]) {
        if (Tags) {
            return Tags.reduce((acc, { Key, Value }): any => {
                if (StandardMeasurementEntity.allowedTags.includes(Key)) {
                    acc[Key] = Value;
                }
                return acc;
            }, {});
        } else {
            return {};
        }
    }

    /**
     * Mirrors the key of a source object so it can be stored, relative to a bucket, inside of the Dead Letter Queue.
     * Absolute locations, like `s3://bucket/key` or `arn:aws:s3:::bucket/key`, are made relative,
     * keys which are already relative are kept as they are.
     */
    static getRelativeSourceKey(sourceKey: string) {
        if (!sourceKey) {
            return '';
        }
        let relativeKey = `${sourceKey}`.trim();
        if (relativeKey.startsWith('arn:aws:s3:::')) {
            relativeKey =<REDACTED>
            relativeKey =<REDACTED>
        } else if (relativeKey.includes('://')) {
            relativeKey =<REDACTED>
            relativeKey =<REDACTED>
        }
        relativeKey =<REDACTED>
        const ingestionBucket = process.env.DB_MEASUREMENT_BUCKET_NAME;
        if (ingestionBucket && relativeKey.startsWith(`${ingestionBucket}/`)) {
            relativeKey =<REDACTED>
        }
        return relativeKey;
    }

    /**
     * Delivers a record, which failed processing, into the Dead Letter Queue.
     * The failure is stored under the mirrored key of the source object,
     * so a failed record can always be traced back to the record which was delivered to Paigo.
     */
    static async publishFailureToDLQ(failure: MeasurementFailure) {
        const { s3Key, sourceKey, key, message, input, error, businessID, bucket } = failure ? failure : {};
        const providedKey = s3Key ? s3Key : sourceKey ? sourceKey : key;
        const relativeKey = StandardMeasurementEntity.getRelativeSourceKey(providedKey);
        const failedInput = input !== undefined ? input : message;
        const Bucket = bucket ? bucket : `${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}`;
        const Key = `${relativeKey ? relativeKey : `${businessID ? businessID : 'unknown'}/${randomUUID()}`}${DLQ_MESSAGE_SUFFIX}`;
        const failureRecord = {
            message: failedInput,
            input: failedInput,
            error: error?.message ? error.message : error ? `${error}` : 'Failed to process usage record',
            s3Key: providedKey,
            businessID,
            timeStamp: new Date().toISOString(),
        };
        const Body = JSON.stringify(failureRecord);
        try {
            const s3 = new S3({ region: process.env.AWS_REGION });
            await s3.putObject({ Bucket, Key, Body });
        } catch (e) {
            AuditService.publishEvent({
                data: [{ e }],
                message: 'Failed to publish Measurement failure to the DLQ',
                topic: AuditScope.ERROR,
            });
            return { message: 'Failed to publish to DLQ', id: randomUUID(), data: [failureRecord] };
        }
        return { message: 'Published to DLQ', id: randomUUID(), data: [failureRecord] };
    }
}

