import { Body, Controller, Logger, Post, Req, UseGuards } from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { ApiBadRequestResponse, ApiCreatedResponse, ApiOperation, ApiTags } from '@nestjs/swagger';
import { BasicResponseDTO } from '../basicResponseDTO';
import { CreateUsageDto } from './dto/create-usage.dto';
import { UsageService } from './usage.service';
import { Request } from 'express';
import { DbMeasuredusageDto } from './dto/dbmeasuredUsage.dto';
import { LogGaurd } from '../authz/logGaurd';
import { StandardMeasurementEntity } from '../measurement-config/entities/standardMeasurement.entity';

@ApiTags('Usage')
@Controller('usage')
export class UsageController {
    private static readonly logger = new Logger(UsageController.name);
    constructor(private readonly usageService: UsageService) {}

    /**
     * Collect usage data by API-based method.
     * See <a href="https://docs.paigo.tech/measure-usage-and-collect-data/measure-and-collect-usage-data-at-production-scale">Measure and Collect Usage Data At Production Scale</a>
     * for full documentation on Paigo <b>Usage Measurement and Collection</b>.
     * @param createUsageDto
     * @param request
     */
    @ApiCreatedResponse({
        status: 201,
        description: 'OK',
        type: BasicResponseDTO,
    })
    @ApiBadRequestResponse({
        status: 400,
        description: 'Bad Request',
        type: BasicResponseDTO,
    })
    @ApiOperation({ operationId: 'Collect usage data' })
    @UseGuards(AuthGuard('jwt'))
    @Post()
    create(@Body() createUsageDto: CreateUsageDto, @Req() request: Request) {
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        //@ts-ignore
        const { businessID } = request.user;
        return this.usageService.create({ ...createUsageDto, businessID });
    }
}

/**
 * The internal endpoints used by the connectors which ingest usage records out of a datastore.
 * These endpoints are not part of the public API.
 */
@ApiTags('Usage')
@Controller('usage')
export class PrivateAPIUsageController {
    private static readonly logger = new Logger(PrivateAPIUsageController.name);
    constructor(private readonly usageService: UsageService) {}

    /**
     * Collect usage data by datastore-based method.
     * Every record delivered by the connector holds a single standard usage record,
     * and the key of the object the record was delivered in.
     * The first segment of that key is the businessID which produced the record.
     * Records which cannot be processed are delivered to the Dead Letter Queue for manual processing.
     *
     * @param createUsageDto
     */
    @UseGuards(LogGaurd, AuthGuard('jwt'))
    @Post('db')
    async dbUsage(@Body() createUsageDto: DbMeasuredusageDto | any) {
        // Custom validator for DB usage, on failure push to DLQ for manual processing

        PrivateAPIUsageController.logger.log('Starting DB Usage Endpoint execution');

        const { message, s3Key } = createUsageDto ? createUsageDto : ({} as DbMeasuredusageDto);
        // TODO: check if the passed in BusinessID is an authorized producer, if not throw message away
        let businessID: string;
        try {
            if (!s3Key) {
                throw new Error('No s3Key was provided with the usage record');
            }
            [businessID] = `${s3Key}`.split('/');
            if (!businessID) {
                throw new Error(`Unable to determine the businessID of the usage record delivered to: ${s3Key}`);
            }
            const parsed = typeof message === 'string' ? JSON.parse(message) : message;
            if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
                throw new Error('The usage record delivered is not a single usage record');
            }
            const input = { ...parsed, businessID };
            return await this.usageService.create(input);
        } catch (error) {
            PrivateAPIUsageController.logger.error(
                `Failed to process the usage record delivered to: ${s3Key}`,
                error?.message
            );
            return StandardMeasurementEntity.publishFailureToDLQ({
                s3Key,
                message,
                error,
                businessID,
            });
        }
    }
}

