import { Test, TestingModule } from '@nestjs/testing';
import { mockClient } from 'aws-sdk-client-mock';
import {
    CreateRoleCommand,
    IAMClient,
    PutRolePolicyCommand,
    UpdateAssumeRolePolicyCommand,
} from '@aws-sdk/client-iam';
import { InfluxService } from '../influx/influx.service';
import { SchedulerService } from '../scheduler/scheduler.service';
import { DimensionsService } from '../dimensions/dimensions.service';
import { MeasurementConfigService } from './measurement-config.service';
import { measurementMode } from './dto/create-measurement-config.dto';
import { DatastoreAccessInformation, SupportedDatastores } from './entities/measurement-config.entity';

const iamMock = mockClient(IAMClient);

describe('Datastore based measurements', () => {
    let service: MeasurementConfigService;
    const businessID = 'fakeBusiness';
    const accountId = '623673123435';
    const roleArn = 'arn:aws:iam::214826386939:role/datastore-fakeBusiness-fakeMeasurement';
    const mockLoadPoints = jest.fn();
    const tag = jest.fn();
    let storedMeasurement: Record<string, any>;

    beforeAll(() => {
        process.env.DB_MEASUREMENT_BUCKET_NAME = 'paigo-usage-record-dump-bucket';
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'paigo-usage-record-dlq-bucket';
        process.env.AWS_REGION = 'us-east-1';
    });

    beforeEach(async () => {
        iamMock.reset();
        iamMock.on(CreateRoleCommand).resolves({ Role: { Arn: roleArn } as any });
        iamMock.on(PutRolePolicyCommand).resolves({});
        iamMock.on(UpdateAssumeRolePolicyCommand).resolves({});
        storedMeasurement = {
            measurementId: 'fakeMeasurement',
            _value: measurementMode.datastoreBased,
            businessID,
            measurementName: 'fakeMeasurementName',
            subject: 'fakeSubject',
            platform: SupportedDatastores.s3,
            accountId,
            region: 'us-east-1',
            iamRoleArn: roleArn,
            externalId: 'existing-external-id',
            ingestion: `s3://paigo-usage-record-dump-bucket/${businessID}`,
            dlq: `s3://paigo-usage-record-dlq-bucket/${businessID}`,
        };

        const module: TestingModule = await Test.createTestingModule({
            providers: [MeasurementConfigService],
            imports: [],
        })
            .useMocker((token) => {
                if (token === InfluxService) {
                    return {
                        loadPoints: mockLoadPoints,
                        getPoint: () => ({ tag, stringField: jest.fn() }),
                        readMeasurementConfigData: () => [storedMeasurement],
                    };
                }
                if (token === SchedulerService) {
                    return { create: jest.fn() };
                }
                if (token === DimensionsService) {
                    return { transformDtoToEntityInput: jest.fn(), findOneByDimensionId: jest.fn() };
                }
            })
            .compile();

        service = module.get<MeasurementConfigService>(MeasurementConfigService);
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    it('provisions a dedicated IAM role trusting the account of the business', async () => {
        const response = await service.create(
            {
                measurementMode: measurementMode.datastoreBased,
                measurementConfiguration: { platform: SupportedDatastores.s3, accountId } as any,
                businessID,
                measurementName: 'fakeMeasurementName',
            },
            'fakeSubject'
        );

        const { measurementId, measurementConfiguration } = response;
        const configuration = measurementConfiguration as DatastoreAccessInformation;

        expect(configuration.platform).toEqual(SupportedDatastores.s3);
        expect(configuration.accountId).toEqual(accountId);
        expect(configuration.region).toEqual('us-east-1');
        expect(configuration.iamRoleArn).toEqual(roleArn);
        expect(configuration.externalId).toBeTruthy();
        expect(configuration.ingestion).toContain(businessID);
        expect(configuration.dlq).toContain(businessID);

        const [createRoleCall] = iamMock.commandCalls(CreateRoleCommand);
        const { RoleName, AssumeRolePolicyDocument } = createRoleCall.args[0].input;
        expect(RoleName).toEqual(`datastore-${businessID}-${measurementId}`);
        const trustPolicy = JSON.parse(AssumeRolePolicyDocument);
        expect(trustPolicy.Statement[0].Principal.AWS).toEqual(`arn:aws:iam::${accountId}:root`);
        expect(trustPolicy.Statement[0].Condition.StringEquals['sts:ExternalId']).toEqual(configuration.externalId);

        const [putRolePolicyCall] = iamMock.commandCalls(PutRolePolicyCommand);
        const { RoleName: policyRoleName, PolicyDocument } = putRolePolicyCall.args[0].input;
        expect(policyRoleName).toEqual(`datastore-${businessID}-${measurementId}`);
        expect(PolicyDocument).toContain(`arn:aws:s3:::paigo-usage-record-dump-bucket/${businessID}/*`);
        expect(PolicyDocument).toContain(`arn:aws:s3:::paigo-usage-record-dlq-bucket/${businessID}/*`);
    });

    it('persists the generated access information', async () => {
        await service.create(
            {
                measurementMode: measurementMode.datastoreBased,
                measurementConfiguration: { accountId } as any,
                businessID,
            },
            'fakeSubject'
        );
        expect(mockLoadPoints).toHaveBeenCalled();
        const taggedKeys = tag.mock.calls.map(([key]) => key);
        ['platform', 'accountId', 'region', 'iamRoleArn', 'externalId', 'ingestion', 'dlq'].forEach((key) =>
            expect(taggedKeys).toContain(key)
        );
    });

    it('defaults the platform and the region', async () => {
        const { measurementConfiguration } = await service.create(
            {
                measurementMode: measurementMode.datastoreBased,
                measurementConfiguration: { accountId } as any,
                businessID,
            },
            'fakeSubject'
        );
        const { platform, region } = measurementConfiguration as DatastoreAccessInformation;
        expect(platform).toEqual('s3');
        expect(region).toEqual('us-east-1');
    });

    it('updates the trust of the role while preserving the role and the external ID', async () => {
        const updatedAccountId = '999999999999';
        const { measurementConfiguration } = await service.update(
            {
                measurementId: 'fakeMeasurement',
                businessID,
                measurementName: undefined,
                measurementConfiguration: { accountId: updatedAccountId } as any,
            },
            'fakeSubject'
        );
        const configuration = measurementConfiguration as DatastoreAccessInformation;
        expect(configuration.accountId).toEqual(updatedAccountId);
        expect(configuration.iamRoleArn).toEqual(roleArn);
        expect(configuration.externalId).toEqual('existing-external-id');

        expect(iamMock.commandCalls(CreateRoleCommand)).toHaveLength(0);
        const [updateTrustCall] = iamMock.commandCalls(UpdateAssumeRolePolicyCommand);
        const { RoleName, PolicyDocument } = updateTrustCall.args[0].input;
        expect(RoleName).toEqual(`datastore-${businessID}-fakeMeasurement`);
        const trustPolicy = JSON.parse(PolicyDocument);
        expect(trustPolicy.Statement[0].Principal.AWS).toEqual(`arn:aws:iam::${updatedAccountId}:root`);
        expect(trustPolicy.Statement[0].Condition.StringEquals['sts:ExternalId']).toEqual('existing-external-id');
    });

    it('reads the stored configuration back', async () => {
        const {
            data: [{ measurementConfiguration }],
        } = await service.findOne({ measurementId: 'fakeMeasurement', businessID });
        const configuration = measurementConfiguration as DatastoreAccessInformation;
        expect(configuration.accountId).toEqual(accountId);
        expect(configuration.platform).toEqual('s3');
        expect(configuration.iamRoleArn).toEqual(roleArn);
        expect(configuration.externalId).toEqual('existing-external-id');
        expect(configuration.ingestion).toEqual(`s3://paigo-usage-record-dump-bucket/${businessID}`);
        expect(configuration.dlq).toEqual(`s3://paigo-usage-record-dlq-bucket/${businessID}`);
    });
});

