import { PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
import { mockClient } from 'aws-sdk-client-mock';
import { StandardMeasurementEntity } from '../measurement-config/entities/standardMeasurement.entity';
import { PrivateAPIUsageController } from './usage.controller';
import { UsageService } from './usage.service';

const s3Mock = mockClient(S3Client);

describe('PrivateAPIUsageController', () => {
    const businessID = 'fakeBusiness';
    const create = jest.fn();
    const usageService = { create } as unknown as UsageService;
    const controller = new PrivateAPIUsageController(usageService);
    const usageRecord = {
        timeStamp: '2023-02-08T19:24:10Z',
        dimensionId: 'da9611bd-e0f3-4c0d-a754-fda5be730872',
        applicationId: 'e8366954-6f36-47e9-8431-ac95f88b5cc7',
        recordValue: 1,
    };

    beforeAll(() => {
        process.env.DB_MEASUREMENT_BUCKET_NAME = 'paigo-usage-record-dump-bucket';
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'paigo-usage-record-dlq-bucket';
        process.env.AWS_REGION = 'us-east-1';
    });

    beforeEach(() => {
        s3Mock.reset();
        s3Mock.on(PutObjectCommand).resolves({});
        create.mockReset().mockResolvedValue({ message: 'Measurement created' });
    });

    it('sends every valid record through the usage service with the businessID of the source key', async () => {
        const response = await controller.dbUsage({
            message: JSON.stringify(usageRecord),
            s3Key: `${businessID}/topics/usage/partition=0/record.json`,
        });

        expect(create).toHaveBeenCalledWith({ ...usageRecord, businessID });
        expect(response).toEqual({ message: 'Measurement created' });
        expect(s3Mock.commandCalls(PutObjectCommand)).toHaveLength(0);
    });

    it('delivers malformed records to the DLQ, mirroring the source key', async () => {
        const s3Key = `${businessID}/topics/usage/partition=0/record.json`;
        await controller.dbUsage({ message: '{"recordValue": ', s3Key });

        const [putObjectCall] = s3Mock.commandCalls(PutObjectCommand);
        const { Bucket, Key, Body } = putObjectCall.args[0].input;
        expect(Bucket).toEqual('paigo-usage-record-dlq-bucket');
        expect(Key).toEqual(`${s3Key}.message.text`);
        const failure = JSON.parse(`${Body}`);
        expect(failure.message).toEqual('{"recordValue": ');
        expect(failure.error).toBeTruthy();
        expect(failure.businessID).toEqual(businessID);
        expect(failure.timeStamp).toBeTruthy();
        expect(create).not.toHaveBeenCalled();
    });

    it('delivers records without a source key to the DLQ', async () => {
        await controller.dbUsage({ message: JSON.stringify(usageRecord) });
        expect(create).not.toHaveBeenCalled();
        const [putObjectCall] = s3Mock.commandCalls(PutObjectCommand);
        expect(putObjectCall.args[0].input.Key).toContain('.message.text');
    });

    it('mirrors absolute and relative source keys into the DLQ', async () => {
        await StandardMeasurementEntity.publishFailureToDLQ({
            s3Key: `s3://paigo-usage-record-dump-bucket/${businessID}/record.json`,
            message: 'not a record',
            error: new Error('Unexpected end of JSON input'),
        });
        await StandardMeasurementEntity.publishFailureToDLQ({
            s3Key: `${businessID}/record.json`,
            message: 'not a record',
            error: new Error('Unexpected end of JSON input'),
        });

        const keys = s3Mock.commandCalls(PutObjectCommand).map(({ args: [{ input }] }) => input.Key);
        expect(keys).toEqual([
            `${businessID}/record.json.message.text`,
            `${businessID}/record.json.message.text`,
        ]);
    });
});

