export enum SupportedDatastores {
    s3 = 's3',
}

/**
 * The context needed to provision and identify the access resources of a datastore based measurement.
 */
export interface DatastoreAccessContext {
    businessID?: string;
    measurementId?: string;
}

/**
 * The default region used for datastore based measurements when none is provided
 */
export const DEFAULT_DATASTORE_REGION = 'us-east-1';

/**
 *
 * This Class represents the access information and control data structure for Datastore based Measurement solutions
 * Specifically this is the access information needed for connectors inside of Confluent Cloud to pull data from a clients env.
 * There are many different connectors with different access and control needs.
 * For example a MySQL connector is not the same as a Kinesis Connector
 * */
export class DatastoreAccessInformation {
    /**
     * Underlying datastore platform which paigo ingests usage records from. Optional, default is `s3`.
     *
     */
    @Matches(
        `^${Object.values(SupportedDatastores)
            .filter((v) => typeof v !== 'number')
            .join('|')}$`,
        'i'
    )
    @IsOptional()
    @ApiProperty({
        enum: SupportedDatastores,
        isArray: false,
        required: false,
        examples: ['s3'],
    })
    public platform?: SupportedDatastores;

    /**
     * The Unqiue ID for the cloud account which produces the usage records. Required.
     * @example "623673123435"
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty({ example: '623673123435' })
    public accountId: string;

    /**
     *
     * The region associated with the ingestion location. Optional, default is `us-east-1`.
     *
     * @example "us-east-1"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, example: DEFAULT_DATASTORE_REGION })
    public region?: string;

    /**
     * The IAM role generated by Paigo which can be assumed to deliver usage records. Read only.
     * <br><br>
     * Example "arn:aws:iam::214826386939:role/datastore-myBusiness-de388932"

                    Resource: [`arn:aws:s3:::${ingestionBucket}`, `arn:aws:s3:::${dlqBucket}`],
                    Condition: {
                        StringLike: {
                            's3:prefix': [`${businessID}/*`],
                        },
                    },
                },
            ],
        };
    }

    /**
     * The location, inside of the paigo hosted datastore, dedicated to a business
     */
    public static getLocation(bucket: string, businessID: string) {
        return `s3://${bucket}/${businessID}`;
    }

    /**
     * Extracts the name of a role out of its ARN
     */
    public static getRoleNameFromArn(iamRoleArn: string) {
        if (iamRoleArn && iamRoleArn.includes('/')) {
            return iamRoleArn.split('/').pop();
        }
        return undefined;
    }

    /**
     * Provisions all of the access needed for a business to deliver usage records into the paigo hosted datastore.
     * A dedicated IAM role, and IAM policy, is created for every measurement.
     * The role can only be assumed by the customers account, with the generated external ID,
     * and can only reach the prefixes owned by the business.
     */
    public static async setupAccess(
        dbAccessInformation: DatastoreAccessInformation,
        context: DatastoreAccessContext = {}
    ): Promise<DatastoreAccessInformation> {
        const businessID = dbAccessInformation?.businessID ? dbAccessInformation.businessID : context?.businessID;
        const measurementId = context?.measurementId
            ? context.measurementId
            : (dbAccessInformation as DatastoreAccessInformation & { measurementId?: string })?.measurementId;

        const configuration = new DatastoreAccessInformation({
            ...dbAccessInformation,
            businessID,
        } as DatastoreAccessInformation);

        if (configuration.platform !== SupportedDatastores.s3) {
            return configuration;
        }

        const roleName = DatastoreAccessInformation.getRoleName(businessID, measurementId);
        const externalId = configuration.externalId ? configuration.externalId : randomUUID();
        const trustPolicy = DatastoreAccessInformation.getTrustPolicy(configuration.accountId, externalId);
        const accessPolicy = DatastoreAccessInformation.getAccessPolicy(businessID);

        try {
            const iam = new IAM({ region: process.env.AWS_REGION });
            const createdRole = await iam.createRole({
                RoleName: roleName,
                AssumeRolePolicyDocument: JSON.stringify(trustPolicy),
            });
            await iam.putRolePolicy({
                RoleName: roleName,
                PolicyName: roleName,
                PolicyDocument: JSON.stringify(accessPolicy),
            });
            configuration.iamRoleArn = createdRole?.Role?.Arn
                ? createdRole.Role.Arn
                : `arn:aws:iam::${configuration.accountId}:role/${roleName}`;
        } catch (e) {
            throw DatastoreAccessInformation.accessError(e, configuration.accountId);
        }

        configuration.externalId = externalId;
        configuration.ingestion = DatastoreAccessInformation.getLocation(
            `${process.env.DB_MEASUREMENT_BUCKET_NAME}`,
            businessID
        );
        configuration.dlq = DatastoreAccessInformation.getLocation(
            `${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}`,
            businessID
        );

        return configuration;
    }

    /**
     * Updates the trust of the IAM role belonging to a datastore based measurement.
     * The role, and its external ID, are preserved so that already delivered access information stays valid.
     */
    public static async updateAccess(
        dbAccessInformation: DatastoreAccessInformation,
        context: DatastoreAccessContext = {}
    ): Promise<DatastoreAccessInformation> {
        const businessID = dbAccessInformation?.businessID ? dbAccessInformation.businessID : context?.businessID;
        const measurementId = context?.measurementId
            ? context.measurementId
            : (dbAccessInformation as DatastoreAccessInformation & { measurementId?: string })?.measurementId;

        const configuration = new DatastoreAccessInformation({
            ...dbAccessInformation,
            businessID,
        } as DatastoreAccessInformation);

        if (configuration.platform !== SupportedDatastores.s3) {
            return configuration;
        }

        const roleNameFromArn = DatastoreAccessInformation.getRoleNameFromArn(configuration.iamRoleArn);
        const roleName = roleNameFromArn
            ? roleNameFromArn
            : DatastoreAccessInformation.getRoleName(businessID, measurementId);
        const externalId = configuration.externalId ? configuration.externalId : randomUUID();
        const trustPolicy = DatastoreAccessInformation.getTrustPolicy(configuration.accountId, externalId);

        try {
            const iam = new IAM({ region: process.env.AWS_REGION });
            await iam.updateAssumeRolePolicy({
                RoleName: roleName,
                PolicyDocument: JSON.stringify(trustPolicy),
            });
        } catch (e) {
            throw DatastoreAccessInformation.accessError(e, configuration.accountId);
        }

        configuration.externalId = externalId;
        if (!configuration.iamRoleArn) {
            configuration.iamRoleArn = `arn:aws:iam::${configuration.accountId}:role/${roleName}`;
        }
        configuration.ingestion = configuration.ingestion
            ? configuration.ingestion
            : DatastoreAccessInformation.getLocation(`${process.env.DB_MEASUREMENT_BUCKET_NAME}`, businessID);
        configuration.dlq = configuration.dlq
            ? configuration.dlq
            : DatastoreAccessInformation.getLocation(`${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}`, businessID);

        return configuration;
    }

    private static accessError(e: any, accountId: string) {
        const code = e?.Code ? e.Code : e?.name;
        const invalidAccountCodes = [
            'MalformedPolicy',
            'MalformedPolicyDocument',
            'MalformedPolicyDocumentException',
            'InvalidInput',
            'InvalidInputException',
        ];
        if (code && invalidAccountCodes.includes(code)) {
            return new BadRequestException(`AccountId: ${accountId} is invalid`);
        }
        return e;
    }
}

