+    /**
+     * Mirrors the key of a source object so it can be stored, relative to a bucket, inside of the Dead Letter Queue.
+     * Absolute locations, like `s3://bucket/key` or `arn:aws:s3:::bucket/key`, are made relative,
+     * keys which are already relative are kept as they are.
+     */
+    static getRelativeSourceKey(sourceKey: string) {
+        if (!sourceKey) {
+            return '';
+        }
+        let relativeKey = `${sourceKey}`.trim();
+        if (relativeKey.startsWith('arn:aws:s3:::')) {
+            relativeKey = relativeKey.replace('arn:aws:s3:::', '');
+            relativeKey = relativeKey.split('/').slice(1).join('/');
+        } else if (relativeKey.includes('://')) {
+            relativeKey = relativeKey.split('://').slice(1).join('://');
+            relativeKey = relativeKey.split('/').slice(1).join('/');
+        }
+        relativeKey = relativeKey.replace(/^\/+/, '');
+        const ingestionBucket = process.env.DB_MEASUREMENT_BUCKET_NAME;
+        if (ingestionBucket && relativeKey.startsWith(`${ingestionBucket}/`)) {
+            relativeKey = relativeKey.slice(`${ingestionBucket}/`.length);
+        }
+        return relativeKey;
+    }
+
+    /**
+     * Delivers a record, which failed processing, into the Dead Letter Queue.
+     * The failure is stored under the mirrored key of the source object,
+     * so a failed record can always be traced back to the record which was delivered to Paigo.
+     */
+    static async publishFailureToDLQ(failure: MeasurementFailure) {
